1	/**
2	 * MergeConflictResolver — shows a side-by-side card for a single duplicate
3	 * pair and lets the user choose: merge vs keep both, and per-field choices
4	 * (Use A / Use B / Combine) for conflicting fields.
5	 */
6	
7	import { useTranslation } from "react-i18next";
8	import { Badge } from "@/components/ui/badge";
9	import { Label } from "@/components/ui/label";
10	import {
11	  Select,
12	  SelectContent,
13	  SelectItem,
14	  SelectTrigger,
15	  SelectValue,
16	} from "@/components/ui/select";
17	import { MemberDB } from "@/types/member";
18	import { DuplicatePair, MergeFieldChoice } from "@/types/merge";
19	import {
20	  COMBINABLE_FIELDS,
21	  RESOLVABLE_FIELDS,
22	  PairResolutionState,
23	  getMemberField,
24	  isFieldConflicting,
25	  memberDisplayName,
26	} from "@/utils/mergeUtils";
27	
28	interface Props {
29	  pair: DuplicatePair;
30	  sourceAName: string;
31	  sourceBName: string;
32	  state: PairResolutionState;
33	  onChange: (updated: PairResolutionState) => void;
34	}
35	
36	function FieldRow({
37	  field,
38	  memberA,
39	  memberB,
40	  isConflict,
41	  action,
42	  fieldChoice,
43	  onChoiceChange,
44	  sourceAName,
45	  sourceBName,
46	}: {
47	  field: string;
48	  memberA: MemberDB;
49	  memberB: MemberDB;
50	  isConflict: boolean;
51	  action: "merge" | "keep_both";
52	  fieldChoice: MergeFieldChoice | undefined;
53	  onChoiceChange: (choice: MergeFieldChoice) => void;
54	  sourceAName: string;
55	  sourceBName: string;
56	}) {
57	  const { t } = useTranslation(undefined, {
58	    keyPrefix: "merge-view.resolve",
59	  });
60	
61	  const va = getMemberField(memberA, field);
62	  const vb = getMemberField(memberB, field);
63	
64	  const displayA = va || "—";
65	  const displayB = vb || "—";
66	  const isCombinableField = COMBINABLE_FIELDS.includes(field);
67	
68	  return (
69	    <div
70	      className={`grid grid-cols-[1fr_1fr_auto] gap-2 items-start py-2 px-3 rounded-sm ${
71	        isConflict
72	          ? "bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800"
73	          : "bg-muted/30"
74	      }`}
75	    >
76	      {/* Source A value */}
77	      <div className="min-w-0">
78	        <div className="text-xs text-muted-foreground mb-0.5">
79	          {sourceAName}
80	        </div>
81	        <div className="text-sm break-words">{displayA}</div>
82	      </div>
83	
84	      {/* Source B value */}
85	      <div className="min-w-0">
86	        <div className="text-xs text-muted-foreground mb-0.5">
87	          {sourceBName}
88	        </div>
89	        <div className="text-sm break-words">{displayB}</div>
90	      </div>
91	
92	      {/* Choice selector (only shown when merging and there's a real conflict) */}
93	      <div className="w-28">
94	        {isConflict && action === "merge" ? (
95	          <Select
96	            value={fieldChoice ?? "a"}
97	            onValueChange={(v) => onChoiceChange(v as MergeFieldChoice)}
98	          >
99	            <SelectTrigger className="h-7 text-xs">
100	              <SelectValue />
101	            </SelectTrigger>
102	            <SelectContent>
103	              <SelectItem value="a">{t("field-choice-a")}</SelectItem>
104	              <SelectItem value="b">{t("field-choice-b")}</SelectItem>
105	              {isCombinableField && (
106	                <SelectItem value="combine">
107	                  {t("field-choice-combine")}
108	                </SelectItem>
109	              )}
110	            </SelectContent>
111	          </Select>
112	        ) : (
113	          <span className="text-xs text-muted-foreground">
114	            {isConflict ? "—" : t("no-conflict")}
115	          </span>
116	        )}
117	      </div>
118	    </div>
119	  );
120	}
121	
122	export const MergeConflictResolver = ({
123	  pair,
124	  sourceAName,
125	  sourceBName,
126	  state,
127	  onChange,
128	}: Props) => {
129	  const { t } = useTranslation(undefined, {
130	    keyPrefix: "merge-view.resolve",
131	  });
132	
133	  const handleActionChange = (action: "merge" | "keep_both") => {
134	    onChange({ ...state, action });
135	  };
136	
137	  const handleFieldChoice = (field: string, choice: MergeFieldChoice) => {
138	    onChange({
139	      ...state,
140	      fields: { ...state.fields, [field]: choice },
141	    });
142	  };
143	
144	  // Only show fields that have at least one non-empty value in either member
145	  const visibleFields = RESOLVABLE_FIELDS.filter((field) => {
146	    const va = getMemberField(pair.member_a, field);
147	    const vb = getMemberField(pair.member_b, field);
148	    return (va || "").trim() || (vb || "").trim();
149	  });
150	
151	  return (
152	    <div className="border rounded-md overflow-hidden">
153	      {/* Header: member names + match badge + action toggle */}
154	      <div className="flex items-center justify-between gap-4 px-4 py-3 bg-muted/50 border-b">
155	        <div className="flex items-center gap-2 min-w-0 flex-1">
156	          <span className="font-medium text-sm truncate">
157	            {memberDisplayName(pair.member_a)}
158	          </span>
159	          <Badge
160	            variant={pair.match === "exact" ? "destructive" : "secondary"}
161	            className="shrink-0 text-xs"
162	          >
163	            {pair.match === "exact" ? t("badge-exact") : t("badge-possible")}
164	          </Badge>
165	        </div>
166	
167	        <div className="flex items-center gap-2 shrink-0">
168	          <Label className="text-xs text-muted-foreground">
169	            {t("action-label")}
170	          </Label>
171	          <Select
172	            value={state.action}
173	            onValueChange={(v) =>
174	              handleActionChange(v as "merge" | "keep_both")
175	            }
176	          >
177	            <SelectTrigger className="h-7 w-28 text-xs">
178	              <SelectValue />
179	            </SelectTrigger>
180	            <SelectContent>
181	              <SelectItem value="merge">{t("action-merge")}</SelectItem>
182	              <SelectItem value="keep_both">{t("action-keep-both")}</SelectItem>
183	            </SelectContent>
184	          </Select>
185	        </div>
186	      </div>
187	
188	      {/* Column headers */}
189	      <div className="grid grid-cols-[1fr_1fr_auto] gap-2 px-3 py-1.5 bg-background border-b">
190	        <div className="text-xs font-medium text-muted-foreground">
191	          {sourceAName}
192	        </div>
193	        <div className="text-xs font-medium text-muted-foreground">
194	          {sourceBName}
195	        </div>
196	        <div className="w-28 text-xs font-medium text-muted-foreground">
197	          {state.action === "merge" ? t("column-choice") : ""}
198	        </div>
199	      </div>
200	
201	      {/* Field rows */}
202	      <div className="p-2 space-y-1 max-h-64 overflow-y-auto">
203	        {visibleFields.length === 0 ? (
204	          <p className="text-sm text-muted-foreground text-center py-4">
205	            {t("no-visible-fields")}
206	          </p>
207	        ) : (
208	          visibleFields.map((field) => (
209	            <FieldRow
210	              key={field}
211	              field={field}
212	              memberA={pair.member_a}
213	              memberB={pair.member_b}
214	              isConflict={isFieldConflicting(pair, field)}
215	              action={state.action}
216	              fieldChoice={state.fields[field]}
217	              onChoiceChange={(choice) => handleFieldChoice(field, choice)}
218	              sourceAName={sourceAName}
219	              sourceBName={sourceBName}
220	            />
221	          ))
222	        )}
223	      </div>
224	    </div>
225	  );
226	};
