1	import { useEffect, useState } from "react";
2	import { useTranslation } from "react-i18next";
3	import { toast } from "sonner";
4	import {
5	  Dialog,
6	  DialogContent,
7	  DialogDescription,
8	  DialogFooter,
9	  DialogHeader,
10	  DialogTitle,
11	} from "@/components/ui/dialog";
12	import { Button } from "@/components/ui/button";
13	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
14	import {
15	  Select,
16	  SelectContent,
17	  SelectItem,
18	  SelectTrigger,
19	  SelectValue,
20	} from "@/components/ui/select";
21	import { useTreeStore } from "@/hooks/useTreeStore";
22	import { TreeService } from "@/services/TreeService";
23	import { ApiError } from "@/services/api";
24	import { Tree } from "@/types/tree";
25	import { DuplicatePair } from "@/types/merge";
26	import {
27	  PairResolutionState,
28	  buildInitialResolutionState,
29	  memberDisplayName,
30	} from "@/utils/mergeUtils";
31	import { MergeConflictResolver } from "@/components/view/database-management-view/dialog/MergeConflictResolver";
32	
33	type Mode = "existing" | "create";
34	
35	interface Props {
36	  /** Id of the tree the member being linked currently lives in (the source
37	   *  side of the bridge, "A" in every conflict). */
38	  sourceTreeId: string;
39	  memberId: string;
40	  memberName: string;
41	  tree: Tree;
42	  open: boolean;
43	  onOpenChange: (open: boolean) => void;
44	  onLinked: () => void;
45	}
46	
47	/**
48	 * Resolves a tree-in-tree bridge person against an already-existing target
49	 * tree, opened from `LinkedTreeField` when the user picks a tree from the
50	 * dropdown. The member must already be saved (bridging writes rows in two
51	 * trees) and the caller must have write access to the target — both are
52	 * enforced by the backend, but the no-access case is also short-circuited
53	 * here from `tree.role` for a friendlier state.
54	 *
55	 * In "find existing person" mode, only same-named candidates from the
56	 * merge/duplicate-detection machinery are offered (#565 follow-up) — picking
57	 * one that conflicts on some fields opens the same `MergeConflictResolver`
58	 * used by tree merge, so differences are resolved instead of left to drift.
59	 */
60	export const LinkExistingTreeDialog = ({
61	  sourceTreeId,
62	  memberId,
63	  memberName,
64	  tree,
65	  open,
66	  onOpenChange,
67	  onLinked,
68	}: Props) => {
69	  const { t } = useTranslation(undefined, {
70	    keyPrefix: "sheet.edit-mode.linked-tree.link-dialog",
71	  });
72	  const linkExistingTree = useTreeStore((s) => s.linkExistingTree);
73	
74	  const [mode, setMode] = useState<Mode>("existing");
75	  const [candidates, setCandidates] = useState<DuplicatePair[]>([]);
76	  const [loading, setLoading] = useState(false);
77	  const [selectedId, setSelectedId] = useState<string | null>(null);
78	  const [resolutionState, setResolutionState] =
79	    useState<PairResolutionState | null>(null);
80	  const [submitting, setSubmitting] = useState(false);
81	
82	  const hasWriteAccess = tree.role === "owner" || tree.role === "editor";
83	
84	  useEffect(() => {
85	    if (!open || !hasWriteAccess) return;
86	    setMode("existing");
87	    setSelectedId(null);
88	    setResolutionState(null);
89	    setLoading(true);
90	    TreeService.getLinkCandidates(sourceTreeId, memberId, tree.id)
91	      .then((res) => setCandidates(res.candidates))
92	      .catch(() => setCandidates([]))
93	      .finally(() => setLoading(false));
94	  }, [open, hasWriteAccess, sourceTreeId, memberId, tree.id]);
95	
96	  const selectedPair =
97	    candidates.find((c) => c.member_b.id === selectedId) ?? null;
98	
99	  const handleSelectCandidate = (id: string) => {
100	    setSelectedId(id);
101	    const pair = candidates.find((c) => c.member_b.id === id);
102	    setResolutionState(pair ? buildInitialResolutionState(pair) : null);
103	  };
104	
105	  const handleConfirm = async () => {
106	    setSubmitting(true);
107	    try {
108	      await linkExistingTree(memberId, {
109	        linked_tree_id: tree.id,
110	        mode,
111	        counterpart_member_id: mode === "existing" ? selectedId : undefined,
112	        field_choices:
113	          mode === "existing" && resolutionState
114	            ? resolutionState.fields
115	            : undefined,
116	      });
117	      toast.success(t("toast-success", { name: tree.name }));
118	      onLinked();
119	      onOpenChange(false);
120	    } catch (err) {
121	      if (err instanceof ApiError && err.status === 409) {
122	        toast.error(t("toast-error-already-linked"));
123	      } else if (err instanceof ApiError && err.status === 403) {
124	        toast.error(t("toast-error-no-access"));
125	      } else {
126	        toast.error(t("toast-error-generic"));
127	      }
128	    } finally {
129	      setSubmitting(false);
130	    }
131	  };
132	
133	  return (
134	    <Dialog open={open} onOpenChange={onOpenChange}>
135	      <DialogContent className="sm:max-w-2xl">
136	        <DialogHeader>
137	          <DialogTitle>{t("title", { name: tree.name })}</DialogTitle>
138	          <DialogDescription>
139	            {t("description", { member: memberName, tree: tree.name })}
140	          </DialogDescription>
141	        </DialogHeader>
142	
143	        {!hasWriteAccess ? (
144	          <p className="text-sm text-muted-foreground">
145	            {t("no-access", { tree: tree.name })}
146	          </p>
147	        ) : (
148	          <Tabs value={mode} onValueChange={(v) => setMode(v as Mode)}>
149	            <TabsList className="w-full">
150	              <TabsTrigger value="existing" className="flex-1">
151	                {t("mode-existing")}
152	              </TabsTrigger>
153	              <TabsTrigger value="create" className="flex-1">
154	                {t("mode-create")}
155	              </TabsTrigger>
156	            </TabsList>
157	            <TabsContent value="existing" className="space-y-2">
158	              <p className="text-xs text-muted-foreground">
159	                {t("mode-existing-description")}
160	              </p>
161	              {!loading && candidates.length === 0 ? (
162	                <p className="text-sm text-muted-foreground">
163	                  {t("no-candidates", { member: memberName, tree: tree.name })}
164	                </p>
165	              ) : (
166	                <Select
167	                  value={selectedId ?? undefined}
168	                  onValueChange={handleSelectCandidate}
169	                  disabled={loading}
170	                >
171	                  <SelectTrigger className="w-full">
172	                    <SelectValue
173	                      placeholder={
174	                        loading ? t("loading") : t("existing-placeholder")
175	                      }
176	                    />
177	                  </SelectTrigger>
178	                  <SelectContent>
179	                    {candidates.map((c) => (
180	                      <SelectItem key={c.member_b.id} value={c.member_b.id}>
181	                        {memberDisplayName(c.member_b)}
182	                        {c.member_b.dateOfBirth
183	                          ? ` (${c.member_b.dateOfBirth})`
184	                          : ""}
185	                      </SelectItem>
186	                    ))}
187	                  </SelectContent>
188	                </Select>
189	              )}
190	
191	              {selectedPair && selectedPair.conflicts.length > 0 && (
192	                <div className="pt-2">
193	                  <MergeConflictResolver
194	                    pair={selectedPair}
195	                    sourceAName={memberName}
196	                    sourceBName={tree.name}
197	                    state={
198	                      resolutionState ??
199	                      buildInitialResolutionState(selectedPair)
200	                    }
201	                    onChange={(updated) =>
202	                      setResolutionState({ ...updated, action: "merge" })
203	                    }
204	                  />
205	                </div>
206	              )}
207	            </TabsContent>
208	            <TabsContent value="create" className="space-y-2">
209	              <p className="text-xs text-muted-foreground">
210	                {t("mode-create-description", {
211	                  member: memberName,
212	                  tree: tree.name,
213	                })}
214	              </p>
215	            </TabsContent>
216	          </Tabs>
217	        )}
218	
219	        <DialogFooter>
220	          <Button
221	            type="button"
222	            variant="outline"
223	            size="sm"
224	            onClick={() => onOpenChange(false)}
225	          >
226	            {t("cancel")}
227	          </Button>
228	          {hasWriteAccess && (
229	            <Button
230	              type="button"
231	              size="sm"
232	              disabled={
233	                submitting ||
234	                (mode === "existing" &&
235	                  (selectedId === null || candidates.length === 0))
236	              }
237	              onClick={() => void handleConfirm()}
238	            >
239	              {t("confirm")}
240	            </Button>
241	          )}
242	        </DialogFooter>
243	      </DialogContent>
244	    </Dialog>
245	  );
246	};
