1	import { useCallback, useEffect, useMemo, useState } from "react";
2	import { useTranslation } from "react-i18next";
3	import { toast } from "sonner";
4	import {
5	  AlertCircle,
6	  AlertTriangle,
7	  Circle,
8	  ClipboardList,
9	  Plus,
10	  ArrowDownToLine,
11	  ArrowUpFromLine,
12	  CheckCircle2,
13	  RefreshCw,
14	  RotateCcw,
15	  ShieldCheck,
16	  X,
17	} from "lucide-react";
18	import { ApiError } from "@/services/api";
19	import { Badge } from "@/components/ui/badge";
20	import { Button } from "@/components/ui/button";
21	import { Card } from "@/components/ui/card";
22	import { Switch } from "@/components/ui/switch";
23	import { ViewLayout } from "@/components/layout/ViewLayout";
24	import { useQualityReportStore } from "@/hooks/useQualityReportStore";
25	import { useTaskStore } from "@/hooks/useTaskStore";
26	import { useDeferredStoreLoad } from "@/hooks/useDeferredStoreLoad";
27	import { useFeature } from "@/hooks/useAuthStore";
28	import { useMemberStore } from "@/hooks/useMemberStore";
29	import { useNavigationStore } from "@/hooks/useNavigationStore";
30	import { useMemberSheetStore } from "@/hooks/useMemberSheetStore";
31	import { useTreeStore } from "@/hooks/useTreeStore";
32	import { TaskDialog } from "@/components/shared/member-sheet/TaskDialog";
33	import type { QualityIssue } from "@/types/quality";
34	
35	const ISSUE_TYPE_KEY: Record<string, string> = {
36	  birth_after_death: "issue-birth-after-death",
37	  child_older_than_parent: "issue-child-older-than-parent",
38	  child_after_parent_death: "issue-child-after-parent-death",
39	  parent_too_young: "issue-parent-too-young",
40	  parent_too_old: "issue-parent-too-old",
41	  relationship_cycle: "issue-relationship-cycle",
42	  duplicate_candidate: "issue-duplicate-candidate",
43	  disconnected_member: "issue-disconnected-member",
44	  bridge_person_drift: "issue-bridge-person-drift",
45	  event_after_death: "issue-event-after-death",
46	};
47	
48	function memberLabel(
49	  memberId: string,
50	  members: ReturnType<typeof useMemberStore.getState>["members"],
51	): string {
52	  const m = members.find((x) => x.id === memberId);
53	  if (!m) return memberId;
54	  const name = [m.firstName, m.lastName].filter(Boolean).join(" ");
55	  return name || memberId;
56	}
57	
58	function useOpenMember(): (memberId: string) => void {
59	  const treeId = useTreeStore((state) => state.selectedTree?.id);
60	  const setOpenSheet = useMemberSheetStore((state) => state.setOpenSheet);
61	  const navigateTo = useNavigationStore((state) => state.navigateTo);
62	
63	  return useCallback(
64	    (memberId: string) => {
65	      if (!treeId) return;
66	      setOpenSheet(treeId, { memberId, tab: "records", mode: "view" });
67	      navigateTo("tree-view");
68	    },
69	    [navigateTo, setOpenSheet, treeId],
70	  );
71	}
72	
73	function IssueCard({
74	  issue,
75	  canWrite,
76	}: {
77	  issue: QualityIssue;
78	  canWrite: boolean;
79	}) {
80	  const { t } = useTranslation(undefined, { keyPrefix: "quality-report-view" });
81	  const { members } = useMemberStore();
82	  const openMember = useOpenMember();
83	  const { dismissIssue, restoreIssue, resolveBridgeDrift } =
84	    useQualityReportStore();
85	  const [resolving, setResolving] = useState(false);
86	
87	  // Bridge-person drift is directly fixable from the note: adopt one side.
88	  // Requires write access to the linked tree too — the backend answers 403
89	  // otherwise, surfaced as a dedicated toast.
90	  const isBridgeDrift = issue.issue_type === "bridge_person_drift";
91	  const handleResolveDrift = async (direction: "push" | "pull") => {
92	    setResolving(true);
93	    try {
94	      await resolveBridgeDrift(issue.member_ids[0], direction);
95	      toast.success(t("resolve-drift-success"));
96	    } catch (err: unknown) {
97	      if (err instanceof ApiError && err.status === 403) {
98	        toast.error(t("resolve-drift-no-access"));
99	      } else {
100	        toast.error(t("resolve-drift-error"));
101	      }
102	    } finally {
103	      setResolving(false);
104	    }
105	  };
106	
107	  const isError = issue.severity === "error";
108	  const Icon = isError ? AlertCircle : AlertTriangle;
109	  const iconClass = isError
110	    ? "text-destructive"
111	    : "text-yellow-500 dark:text-yellow-400";
112	  const typeLabel = t(ISSUE_TYPE_KEY[issue.issue_type] ?? "issue-unknown");
113	
114	  return (
115	    <Card
116	      className={`p-4 flex flex-row gap-4 items-center ${issue.dismissed ? "opacity-60" : ""}`}
117	    >
118	      <div className="mt-0.5 flex-shrink-0">
119	        <Icon className={`w-5 h-5 ${iconClass}`} />
120	      </div>
121	      <div className="flex-1 min-w-0 space-y-2">
122	        <div className="flex items-center gap-2 flex-wrap">
123	          <span className="font-medium text-sm">{typeLabel}</span>
124	          <Badge
125	            variant={isError ? "destructive" : "outline"}
126	            className="text-xs"
127	          >
128	            {t(`severity-${issue.severity}`)}
129	          </Badge>
130	          {issue.dismissed && (
131	            <Badge variant="secondary" className="text-xs">
132	              {t("dismissed-badge")}
133	            </Badge>
134	          )}
135	        </div>
136	        <p className="text-sm text-muted-foreground">{issue.description}</p>
137	        {issue.member_ids.length > 0 && (
138	          <div className="flex flex-wrap gap-1">
139	            {issue.member_ids.map((id) => (
140	              <button
141	                key={id}
142	                className="text-xs px-2 py-0.5 rounded-full bg-muted hover:bg-muted/70 transition-colors font-mono cursor-pointer"
143	                onClick={() => openMember(id)}
144	                title={t("view-member")}
145	              >
146	                {memberLabel(id, members)}
147	              </button>
148	            ))}
149	          </div>
150	        )}
151	        {isBridgeDrift && canWrite && !issue.dismissed && (
152	          <div className="flex flex-wrap gap-2 pt-1">
153	            <Button
154	              variant="outline"
155	              size="sm"
156	              disabled={resolving}
157	              onClick={() => void handleResolveDrift("push")}
158	            >
159	              <ArrowUpFromLine />
160	              {t("resolve-drift-push")}
161	            </Button>
162	            <Button
163	              variant="outline"
