22	export const useQualityReportStore = create<QualityReportState>((set, get) => ({
23	  report: null,
24	  isLoading: false,
25	  showDismissed: false,
26	
27	  refreshReport: async (treeId = activeTreeId()) => {
28	    if (!treeId) {
29	      set({ report: null });
30	      return;
31	    }
32	    set({ isLoading: true });
33	    try {
34	      const report = await TreeService.getQualityReport(treeId);
35	      if (!isActiveTree(treeId)) return; // tree switched/disconnected mid-flight — drop stale data
36	      set({ report });
37	    } finally {
38	      set({ isLoading: false });
39	    }
40	  },
41	
42	  setShowDismissed: (show: boolean) => set({ showDismissed: show }),
43	
44	  dismissIssue: async (issueId: string) => {
45	    const treeId = activeTreeId();
46	    if (!treeId) return;
47	    await TreeService.dismissQualityIssue(treeId, issueId);
48	    await get().refreshReport(treeId);
49	  },
50	
51	  restoreIssue: async (issueId: string) => {
52	    const treeId = activeTreeId();
53	    if (!treeId) return;
54	    await TreeService.restoreQualityIssue(treeId, issueId);
55	    await get().refreshReport(treeId);
56	  },
57	
58	  // Resolve bridge-person drift by copying fields across the tree link
59	  // ("push" = this tree wins, "pull" = the linked tree wins), then reload the
60	  // report and — on pull — the members, whose fields just changed. Errors
61	  // (e.g. 403 without write access to the linked tree) propagate to the view.
62	  resolveBridgeDrift: async (memberId: string, direction: "push" | "pull") => {
63	    const treeId = activeTreeId();
64	    if (!treeId) return;
65	    await TreeService.resolveBridgeDrift(treeId, memberId, direction);
66	    const tasks: Promise<void>[] = [get().refreshReport(treeId)];
67	    if (direction === "pull") {
68	      tasks.push(useMemberStore.getState().refreshMembers(treeId));
69	    }
70	    await Promise.all(tasks);
71	  },
72	
73	  clear: () => set({ report: null, showDismissed: false }),
74	}));
